namespace bg = boost::geometry;
using BoostPoint = bg::model::d2::point_xy<double>;
using BoostPolygon = bg::model::polygon<BoostPoint, false, true>;

static BoostPolygon vector_to_boost_polygon(const std::vector<Point>& pts) {
    BoostPolygon poly;
    auto& out = poly.outer();
    out.clear();
    out.reserve(pts.size() + 1);
    for (const auto& p : pts) {
        out.emplace_back(CGAL::to_double(p.x()), CGAL::to_double(p.y()));
    }
    if (!pts.empty()) {
        out.emplace_back(CGAL::to_double(pts.front().x()), CGAL::to_double(pts.front().y()));
    }
    bg::correct(poly);
    return poly;
}

static double polygon_area_double(const std::vector<Point>& poly) {
    if (poly.size() < 3) return 0.0;
    double area = 0.0;
    for (size_t i = 0; i < poly.size(); ++i) {
        size_t j = (i + 1) % poly.size();
        area += CGAL::to_double(poly[i].x()) * CGAL::to_double(poly[j].y());
        area -= CGAL::to_double(poly[j].x()) * CGAL::to_double(poly[i].y());
    }
    return std::abs(area) / 2.0;
}

static bool boost_polygon_intersection(const std::vector<Point>& P,
                                       const std::vector<Point>& Q,
                                       std::vector<Point>& result) {
    result.clear();
    if (P.size() < 3 || Q.size() < 3) {
        return false;
    }

    BoostPolygon bp = vector_to_boost_polygon(P);
    BoostPolygon bq = vector_to_boost_polygon(Q);
    std::vector<BoostPolygon> output;
    bg::intersection(bp, bq, output);

    if (output.empty()) {
        return false;
    }

    auto best_it = std::max_element(output.begin(), output.end(), [](const BoostPolygon& a, const BoostPolygon& b) {
        return std::abs(bg::area(a)) < std::abs(bg::area(b));
    });
    if (best_it == output.end() || best_it->outer().size() < 4) {
        return false;
    }

    const auto& ring = best_it->outer();
    result.reserve(ring.size() - 1);
    for (size_t i = 0; i + 1 < ring.size(); ++i) {
        result.emplace_back(bg::get<0>(ring[i]), bg::get<1>(ring[i]));
    }
    return result.size() >= 3 && polygon_area_double(result) > 1e-12;
}

