// O'Rourke's O(n+m) convex polygon intersection algorithm
// Input: two convex polygons P and Q
// Output: intersection polygon (CCW) or empty vector if no intersection
std::vector<Point> convex_polygon_intersection(const std::vector<Point>& P_input,
                                                 const std::vector<Point>& Q_input) {
    if (P_input.empty() || Q_input.empty()) return {};

    // Make copies that are guaranteed CCW
    std::vector<Point> P = P_input;
    std::vector<Point> Q = Q_input;

    // Ensure CCW orientation (area should be positive)
    if (CGAL::area(Kernel::Point_2(0,0), P[0], P[1]) < 0) {
        std::reverse(P.begin(), P.end());
    }
    if (CGAL::area(Kernel::Point_2(0,0), Q[0], Q[1]) < 0) {
        std::reverse(Q.begin(), Q.end());
    }

    int n = static_cast<int>(P.size());
    int m = static_cast<int>(Q.size());

    if (n < 3 || m < 3) {
        return {};
    }

    // Scale-aware epsilon based on polygon bounding box
    double min_x =  std::numeric_limits<double>::max();
    double max_x = -std::numeric_limits<double>::max();
    double min_y =  std::numeric_limits<double>::max();
    double max_y = -std::numeric_limits<double>::max();
    for (const auto& p : P) {
        min_x = std::min(min_x, CGAL::to_double(p.x()));
        max_x = std::max(max_x, CGAL::to_double(p.x()));
        min_y = std::min(min_y, CGAL::to_double(p.y()));
        max_y = std::max(max_y, CGAL::to_double(p.y()));
    }
    for (const auto& q : Q) {
        min_x = std::min(min_x, CGAL::to_double(q.x()));
        max_x = std::max(max_x, CGAL::to_double(q.x()));
        min_y = std::min(min_y, CGAL::to_double(q.y()));
        max_y = std::max(max_y, CGAL::to_double(q.y()));
    }
    double scale = std::max(max_x - min_x, max_y - min_y);
    const double EPS = std::max(scale * 1e-10, 1e-12);  // relative to polygon size
    const double CLOSE = std::max(scale * 1e-6, 1e-8);  // duplicate-removal threshold

    // Check for containment (one polygon inside the other)
    bool all_P_in_Q = true;
    bool all_Q_in_P = true;
    for (const auto& p : P) {
        if (!point_in_convex(p, Q, true)) {
            all_P_in_Q = false;
            break;
        }
    }
    if (all_P_in_Q) return P;

    for (const auto& q : Q) {
        if (!point_in_convex(q, P, true)) {
            all_Q_in_P = false;
            break;
        }
    }
    if (all_Q_in_P) return Q;

    // Initialize pointers
    int i = 0, j = 0;  // current vertices
    std::vector<Point> result;

    // Track first intersection to detect completion
    bool first_intersection_found = false;
    Point first_intersection;

    // Maximum iterations (2*(n+m) ensures we visit all edges)
    int max_iterations = 2 * (n + m) + 10;
    int iterations = 0;

    auto cross = [](const Point& o, const Point& a, const Point& b) {
        return (CGAL::to_double(a.x()) - CGAL::to_double(o.x())) * (CGAL::to_double(b.y()) - CGAL::to_double(o.y())) -
               (CGAL::to_double(a.y()) - CGAL::to_double(o.y())) * (CGAL::to_double(b.x()) - CGAL::to_double(o.x()));
    };

    // Advance functions
    auto advance_i = [&]() { i = (i + 1) % n; };
    auto advance_j = [&]() { j = (j + 1) % m; };

    // Compute intersection of two line segments (if any)
    auto segments_intersect = [&](const Point& a1, const Point& a2,
                                   const Point& b1, const Point& b2) -> std::optional<Point> {
        double x1 = CGAL::to_double(a1.x()), y1 = CGAL::to_double(a1.y());
        double x2 = CGAL::to_double(a2.x()), y2 = CGAL::to_double(a2.y());
        double x3 = CGAL::to_double(b1.x()), y3 = CGAL::to_double(b1.y());
        double x4 = CGAL::to_double(b2.x()), y4 = CGAL::to_double(b2.y());

        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (std::abs(denom) < EPS) return std::nullopt;  // parallel

        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;

        if (t >= -EPS && t <= 1.0 + EPS && u >= -EPS && u <= 1.0 + EPS) {
            return Point(x1 + t * (x2 - x1), y1 + t * (y2 - y1));
        }
        return std::nullopt;
    };

    while (iterations < max_iterations) {
        iterations++;

        const Point& pi = P[i];
        const Point& pj = Q[j];
        const Point& p_next_i = P[(i + 1) % n];
        const Point& p_next_j = Q[(j + 1) % m];

        // Output current vertex if inside
        if (point_in_convex(pi, Q, true)) {
            result.push_back(pi);
        }
        if (point_in_convex(pj, P, true)) {
            result.push_back(pj);
        }

        // Check if edges intersect
        auto inter = segments_intersect(pi, p_next_i, pj, p_next_j);

        if (inter) {
            if (!first_intersection_found) {
                first_intersection = *inter;
                first_intersection_found = true;
            } else {
                // Check if we've returned to first intersection
                double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, first_intersection)));
                if (dist < CLOSE && result.size() > 2) {
                    // Avoid duplicate points
                    if (result.empty() ||
                        std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > CLOSE) {
                        result.push_back(*inter);
                    }
                    break;
                }
            }
            // Avoid duplicate points
            if (result.empty() ||
                std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > CLOSE) {
                result.push_back(*inter);
            }
        }

        // Determine which edge to advance
        double cross_val = cross(pi, p_next_i, pj);
        double cross_val2 = cross(pj, p_next_j, pi);

        if (std::abs(cross_val) < EPS && std::abs(cross_val2) < EPS) {
            // Collinear edges - advance both
            advance_i();
            advance_j();
        } else if (cross_val >= 0 && cross_val2 >= 0) {
            // Both edges turn in same direction - advance the one with smaller turn
            if (cross(pi, p_next_i, pj) <= cross(pj, p_next_j, pi)) {
                advance_i();
            } else {
                advance_j();
            }
        } else if (cross_val >= 0) {
            advance_i();
        } else {
            advance_j();
        }

        // Check for termination: back at starting positions with no more intersections
        if (i == 0 && j == 0 && iterations > n + m) {
            break;
        }
    }

    // Remove duplicate consecutive points
    if (result.size() > 1) {
        std::vector<Point> deduped;
        deduped.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(result[k], deduped.back())));
            if (dist > CLOSE) {
                deduped.push_back(result[k]);
            }
        }
        result = deduped;
    }

    // Remove collinear points (keep only vertices)
    if (result.size() > 2) {
        std::vector<Point> clean;
        clean.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            const Point& prev = clean.back();
            const Point& curr = result[k];
            const Point& next = result[(k + 1) % result.size()];

            double area = CGAL::to_double(CGAL::area(prev, curr, next));
            if (std::abs(area) > EPS) {
                clean.push_back(curr);
            }
        }
        result = clean;
    }

    return result;
}

