#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/Exact_predicates_exact_constructions_kernel.h>
#include <CGAL/convex_hull_2.h>
#include <boost/geometry.hpp>
#include <boost/geometry/geometries/point_xy.hpp>
#include <boost/geometry/geometries/polygon.hpp>

#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstdint>
#include <iomanip>
#include <iostream>
#include <random>
#include <string>
#include <vector>

using Exact_kernel = CGAL::Exact_predicates_exact_constructions_kernel;
using Exact_point = Exact_kernel::Point_2;
using Exact_polygon = CGAL::Polygon_2<Exact_kernel>;
using Exact_polygon_with_holes = CGAL::Polygon_with_holes_2<Exact_kernel>;

namespace bg = boost::geometry;
using BoostPoint = bg::model::d2::point_xy<double>;
using BoostPolygon = bg::model::polygon<BoostPoint, false, true>;

struct CaseData {
    std::vector<double> ax;
    std::vector<double> ay;
    std::vector<double> bx;
    std::vector<double> by;
};

static double polygon_area_double(const std::vector<double>& xs, const std::vector<double>& ys) {
    if (xs.size() < 3 || ys.size() != xs.size()) return 0.0;
    double area = 0.0;
    for (size_t i = 0; i < xs.size(); ++i) {
        size_t j = (i + 1) % xs.size();
        area += xs[i] * ys[j] - xs[j] * ys[i];
    }
    return std::abs(area) * 0.5;
}

static BoostPolygon to_boost_polygon(const std::vector<double>& xs, const std::vector<double>& ys) {
    BoostPolygon poly;
    auto& out = poly.outer();
    out.reserve(xs.size() + 1);
    for (size_t i = 0; i < xs.size(); ++i) {
        out.emplace_back(xs[i], ys[i]);
    }
    if (!xs.empty()) {
        out.emplace_back(xs.front(), ys.front());
    }
    bg::correct(poly);
    return poly;
}

static Exact_polygon to_exact_polygon(const std::vector<double>& xs, const std::vector<double>& ys) {
    std::vector<Exact_point> pts;
    pts.reserve(xs.size());
    for (size_t i = 0; i < xs.size(); ++i) {
        pts.emplace_back(xs[i], ys[i]);
    }
    Exact_polygon poly(pts.begin(), pts.end());
    if (!poly.is_counterclockwise_oriented()) {
        poly.reverse_orientation();
    }
    return poly;
}

static bool boost_intersection_has_polygon(const CaseData& data, double& area_out, std::size_t& vertices_out) {
    BoostPolygon a = to_boost_polygon(data.ax, data.ay);
    BoostPolygon b = to_boost_polygon(data.bx, data.by);
    std::vector<BoostPolygon> output;
    bg::intersection(a, b, output);
    if (output.empty()) {
        area_out = 0.0;
        vertices_out = 0;
        return false;
    }

    auto best_it = std::max_element(output.begin(), output.end(), [](const BoostPolygon& lhs, const BoostPolygon& rhs) {
        return std::abs(bg::area(lhs)) < std::abs(bg::area(rhs));
    });
    if (best_it == output.end() || best_it->outer().size() < 4) {
        area_out = 0.0;
        vertices_out = 0;
        return false;
    }

    area_out = std::abs(bg::area(*best_it));
    vertices_out = best_it->outer().size() - 1;
    return area_out > 1e-12;
}

static bool cgal_epeck_intersection_has_polygon(const CaseData& data, double& area_out, std::size_t& vertices_out) {
    Exact_polygon a = to_exact_polygon(data.ax, data.ay);
    Exact_polygon b = to_exact_polygon(data.bx, data.by);
    std::vector<Exact_polygon_with_holes> output;
    CGAL::intersection(a, b, std::back_inserter(output));
    if (output.empty()) {
        area_out = 0.0;
        vertices_out = 0;
        return false;
    }

    auto best_it = std::max_element(output.begin(), output.end(), [](const Exact_polygon_with_holes& lhs, const Exact_polygon_with_holes& rhs) {
        return std::abs(CGAL::to_double(lhs.outer_boundary().area())) < std::abs(CGAL::to_double(rhs.outer_boundary().area()));
    });
    if (best_it == output.end()) {
        area_out = 0.0;
        vertices_out = 0;
        return false;
    }

    const auto& outer = best_it->outer_boundary();
    area_out = std::abs(CGAL::to_double(outer.area()));
    vertices_out = outer.size();
    return vertices_out >= 3 && area_out > 1e-12;
}

static CaseData make_case(std::mt19937_64& rng, int vertices, double radius, double shift_scale) {
    std::uniform_real_distribution<double> angle_dist(0.0, 2.0 * M_PI);
    std::uniform_real_distribution<double> radius_dist(0.35 * radius, radius);
    std::uniform_real_distribution<double> shift_dist(-shift_scale, shift_scale);

    auto make_poly = [&](double cx, double cy) {
        std::vector<std::pair<double, double>> polar;
        polar.reserve(vertices);
        for (int i = 0; i < vertices; ++i) {
            polar.emplace_back(angle_dist(rng), radius_dist(rng));
        }
        std::sort(polar.begin(), polar.end(), [](const auto& lhs, const auto& rhs) {
            return lhs.first < rhs.first;
        });

        std::vector<Exact_point> pts;
        pts.reserve(vertices);
        for (const auto& [angle, r] : polar) {
            pts.emplace_back(cx + r * std::cos(angle), cy + r * std::sin(angle));
        }

        std::vector<Exact_point> hull;
        CGAL::convex_hull_2(pts.begin(), pts.end(), std::back_inserter(hull));

        std::vector<double> xs;
        std::vector<double> ys;
        xs.reserve(hull.size());
        ys.reserve(hull.size());
        for (const auto& p : hull) {
            xs.push_back(CGAL::to_double(p.x()));
            ys.push_back(CGAL::to_double(p.y()));
        }
        return std::pair{xs, ys};
    };

    auto [ax, ay] = make_poly(0.0, 0.0);
    auto [bx, by] = make_poly(shift_dist(rng), shift_dist(rng));
    return CaseData{std::move(ax), std::move(ay), std::move(bx), std::move(by)};
}

int main() {
    constexpr int case_count = 2000;
    constexpr int vertices = 24;
    constexpr double radius = 100.0;
    constexpr double shift_scale = 45.0;

    std::mt19937_64 rng(42);
    std::vector<CaseData> cases;
    cases.reserve(case_count);
    for (int i = 0; i < case_count; ++i) {
        cases.push_back(make_case(rng, vertices, radius, shift_scale));
    }

    using Clock = std::chrono::steady_clock;
    double boost_area_sum = 0.0;
    double cgal_area_sum = 0.0;
    std::size_t boost_vertex_sum = 0;
    std::size_t cgal_vertex_sum = 0;
    int boost_hits = 0;
    int cgal_hits = 0;
    int disagreements = 0;

    auto boost_start = Clock::now();
    for (const auto& test_case : cases) {
        double area = 0.0;
        std::size_t vertices_out = 0;
        bool ok = boost_intersection_has_polygon(test_case, area, vertices_out);
        boost_hits += ok ? 1 : 0;
        boost_area_sum += area;
        boost_vertex_sum += vertices_out;
    }
    auto boost_elapsed = std::chrono::duration<double, std::milli>(Clock::now() - boost_start).count();

    auto cgal_start = Clock::now();
    for (const auto& test_case : cases) {
        double area = 0.0;
        std::size_t vertices_out = 0;
        bool ok = cgal_epeck_intersection_has_polygon(test_case, area, vertices_out);
        cgal_hits += ok ? 1 : 0;
        cgal_area_sum += area;
        cgal_vertex_sum += vertices_out;
    }
    auto cgal_elapsed = std::chrono::duration<double, std::milli>(Clock::now() - cgal_start).count();

    for (const auto& test_case : cases) {
        double boost_area = 0.0;
        double cgal_area = 0.0;
        std::size_t boost_vertices = 0;
        std::size_t cgal_vertices = 0;
        bool boost_ok = boost_intersection_has_polygon(test_case, boost_area, boost_vertices);
        bool cgal_ok = cgal_epeck_intersection_has_polygon(test_case, cgal_area, cgal_vertices);
        bool same = boost_ok == cgal_ok && std::abs(boost_area - cgal_area) <= 1e-6 && boost_vertices == cgal_vertices;
        disagreements += same ? 0 : 1;
    }

    std::cout << std::fixed << std::setprecision(3);
    std::cout << "Boost.Geometry vs CGAL EPECK intersection benchmark\n";
    std::cout << "Cases: " << case_count << ", approx vertices/polygon: " << vertices << "\n\n";

    std::cout << "Boost.Geometry\n";
    std::cout << "  total ms:     " << boost_elapsed << "\n";
    std::cout << "  us / case:    " << (boost_elapsed * 1000.0 / case_count) << "\n";
    std::cout << "  hits:         " << boost_hits << "\n";
    std::cout << "  area sum:     " << boost_area_sum << "\n";
    std::cout << "  vertex sum:   " << boost_vertex_sum << "\n\n";

    std::cout << "CGAL EPECK\n";
    std::cout << "  total ms:     " << cgal_elapsed << "\n";
    std::cout << "  us / case:    " << (cgal_elapsed * 1000.0 / case_count) << "\n";
    std::cout << "  hits:         " << cgal_hits << "\n";
    std::cout << "  area sum:     " << cgal_area_sum << "\n";
    std::cout << "  vertex sum:   " << cgal_vertex_sum << "\n\n";

    std::cout << "Relative speed\n";
    if (boost_elapsed > 0.0) {
        std::cout << "  CGAL / Boost: " << (cgal_elapsed / boost_elapsed) << "x\n";
    }
    std::cout << "  disagreements: " << disagreements << "\n";

    return 0;
}

