std::vector<int> find_tangent_idx(const Point &p,
                                 const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    for (int i = 0; i < n; i++) {
        Point pred = S[(i - 1 + n) % n];
        Point now = S[i];
        Point succ = S[(i + 1 + n) % n];
        auto o1 = CGAL::orientation(p, pred, now);
        auto o2 = CGAL::orientation(p, now, succ);
        if (o1 != o2 && !(o1 == CGAL::COLLINEAR && o2 == CGAL::COLLINEAR)) {
            tangent.push_back(i);
        }
    }

    if (tangent.size() <= 2) {
        return tangent;
    }

    std::vector<int> filtered;
    for (int idx : tangent) {
        bool duplicate_direction = false;
        for (int kept : filtered) {
            if (CGAL::orientation(p, S[kept], S[idx]) == CGAL::COLLINEAR) {
                if (CGAL::compare_distance_to_point(p, S[idx], S[kept]) == CGAL::LARGER) {
                    kept = idx;
                }
                duplicate_direction = true;
                break;
            }
        }
        if (!duplicate_direction) {
            filtered.push_back(idx);
        }
    }

    if (filtered.size() == 2) {
        return filtered;
    }

    if (filtered.size() > 2) {
        std::vector<std::pair<double, int>> angles;
        angles.reserve(filtered.size());
        const double px = CGAL::to_double(p.x());
        const double py = CGAL::to_double(p.y());
        for (int idx : filtered) {
            angles.emplace_back(std::atan2(CGAL::to_double(S[idx].y()) - py,
                                           CGAL::to_double(S[idx].x()) - px),
                                idx);
        }
        std::sort(angles.begin(), angles.end(), [](const auto& a, const auto& b) {
            return a.first < b.first;
        });
        double best_gap = -1.0;
        std::pair<int, int> best_pair{angles.front().second, angles.back().second};
        for (size_t i = 0; i < angles.size(); ++i) {
            size_t j = (i + 1) % angles.size();
            double a1 = angles[i].first;
            double a2 = angles[j].first;
            if (j == 0) {
                a2 += 2.0 * M_PI;
            }
            double gap = a2 - a1;
            if (gap > best_gap) {
                best_gap = gap;
                best_pair = {angles[i].second, angles[j].second};
            }
        }
        return {best_pair.first, best_pair.second};
    }

    return filtered;
}

